package contacts_test

// vCard 4.0 converter tests (REQ-CTS-10..14, REQ-CTS-40).
//
// TestVCard_RoundTrip_* tests assert REQ-CTS-13 (round-trip equivalence)
// for the representative fixture cards listed in the requirement.
//
// Comparison is semantic rather than byte-equal: map keys generated by
// ParseVCards are deterministic ("email/0", "phone/0", …) but differ
// from keys a client might supply; we compare the value sets.

import (
	"encoding/json"
	"fmt"
	"strings"
	"testing"

	"github.com/hanshuebner/herold/internal/protojmap/contacts"
)

// ===== ParseVCards =====

func TestVCard_ParseMinimal(t *testing.T) {
	vcf := "BEGIN:VCARD\r\nVERSION:4.0\r\nFN:Alice\r\nUID:urn:uuid:1\r\nEND:VCARD\r\n"
	results := contacts.ParseVCards([]byte(vcf), nil)
	if len(results) != 1 {
		t.Fatalf("want 1 result, got %d", len(results))
	}
	if results[0].Error != nil {
		t.Fatalf("unexpected error: %v", results[0].Error)
	}
	c := results[0].Card
	if c.UID != "urn:uuid:1" {
		t.Errorf("UID = %q, want urn:uuid:1", c.UID)
	}
	if c.Name == nil || c.Name.Full != "Alice" {
		name := "<nil>"
		if c.Name != nil {
			name = c.Name.Full
		}
		t.Errorf("Name.Full = %q, want Alice", name)
	}
	if c.Version != "1.0" {
		t.Errorf("Version = %q, want 1.0", c.Version)
	}
}

func TestVCard_ParseFull(t *testing.T) {
	vcf := strings.Join([]string{
		"BEGIN:VCARD",
		"VERSION:4.0",
		"UID:urn:uuid:full-1",
		"KIND:individual",
		"FN:Ada Lovelace",
		"N:Lovelace;Ada;Augusta;Hon.;",
		"EMAIL;TYPE=work;PREF=1:ada@example.test",
		"EMAIL;TYPE=home:ada-personal@example.test",
		"TEL;TYPE=voice,work;PREF=1:+44 20 7946 0958",
		"TEL;TYPE=cell:+44 7700 900123",
		"ADR;TYPE=work;CC=GB:;;10 Downing Street;London;;SW1A 2AA;United Kingdom",
		"ORG:Analytical Engine Co.;Research",
		"TITLE:Mathematician",
		"ROLE:Fellow",
		`NICKNAME:Ada\,Countess`,
		"NOTE:Pioneer of computing.",
		"URL;PREF=1:https://lovelace.example.test",
		"BDAY:18151210",
		"ANNIVERSARY:--1225",
		"END:VCARD",
	}, "\r\n") + "\r\n"

	results := contacts.ParseVCards([]byte(vcf), nil)
	if len(results) != 1 {
		t.Fatalf("want 1 result, got %d", len(results))
	}
	if results[0].Error != nil {
		t.Fatalf("parse error: %v", results[0].Error)
	}
	c := results[0].Card

	if c.Kind != "individual" {
		t.Errorf("Kind = %q, want individual", c.Kind)
	}
	if c.Name == nil {
		t.Fatal("Name is nil")
	}
	if c.Name.Full != "Ada Lovelace" {
		t.Errorf("Name.Full = %q, want Ada Lovelace", c.Name.Full)
	}
	assertNameComponent(t, c, "surname", "Lovelace")
	assertNameComponent(t, c, "given", "Ada")
	assertNameComponent(t, c, "middle", "Augusta")
	assertNameComponent(t, c, "prefix", "Hon.")

	if len(c.Emails) != 2 {
		t.Errorf("Emails count = %d, want 2", len(c.Emails))
	}
	assertEmailExists(t, c, "ada@example.test", true)
	assertEmailExists(t, c, "ada-personal@example.test", false)
	assertPrimaryEmail(t, c, "ada@example.test")

	if len(c.Phones) != 2 {
		t.Errorf("Phones count = %d, want 2", len(c.Phones))
	}
	assertPhoneFeature(t, c, "+44 20 7946 0958", "voice")
	assertPhoneFeature(t, c, "+44 7700 900123", "cell")

	if len(c.Addresses) != 1 {
		t.Errorf("Addresses count = %d, want 1", len(c.Addresses))
	}
	for _, a := range c.Addresses {
		if a.CountryCode != "GB" {
			t.Errorf("CountryCode = %q, want GB", a.CountryCode)
		}
		assertAddrComponent(t, a, "city", "London")
		assertAddrComponent(t, a, "postcode", "SW1A 2AA")
	}

	if len(c.Organizations) != 1 {
		t.Errorf("Orgs count = %d, want 1", len(c.Organizations))
	}
	for _, o := range c.Organizations {
		if o.Name != "Analytical Engine Co." {
			t.Errorf("Org.Name = %q", o.Name)
		}
		if len(o.Units) != 1 || o.Units[0] != "Research" {
			t.Errorf("Org.Units = %v, want [Research]", o.Units)
		}
	}

	if len(c.Titles) != 2 {
		t.Errorf("Titles count = %d, want 2", len(c.Titles))
	}
	assertTitleKind(t, c, "Mathematician", "title")
	assertTitleKind(t, c, "Fellow", "role")

	assertRawJSONHasNickname(t, c, "Ada,Countess")
	assertRawJSONHasNote(t, c, "Pioneer of computing.")
	assertRawJSONHasURL(t, c, "https://lovelace.example.test")
	assertRawJSONHasBirthday(t, c, 1815, 12, 10)
	assertRawJSONHasAnniversary(t, c, 0, 12, 25)
}

func TestVCard_ParseMultiple(t *testing.T) {
	vcf := "BEGIN:VCARD\r\nVERSION:4.0\r\nFN:Alice\r\nUID:urn:uuid:a\r\nEND:VCARD\r\n" +
		"BEGIN:VCARD\r\nVERSION:4.0\r\nFN:Bob\r\nUID:urn:uuid:b\r\nEND:VCARD\r\n"

	results := contacts.ParseVCards([]byte(vcf), nil)
	if len(results) != 2 {
		t.Fatalf("want 2 results, got %d", len(results))
	}
	for i, r := range results {
		if r.Error != nil {
			t.Errorf("result[%d] error: %v", i, r.Error)
		}
	}
	names := map[string]bool{
		results[0].Card.Name.Full: true,
		results[1].Card.Name.Full: true,
	}
	if !names["Alice"] || !names["Bob"] {
		t.Errorf("names = %v, want Alice and Bob", names)
	}
}

func TestVCard_ParseMalformed_Truncated(t *testing.T) {
	vcf := "BEGIN:VCARD\r\nVERSION:4.0\r\nFN:Partial" // no END:VCARD
	results := contacts.ParseVCards([]byte(vcf), nil)
	if len(results) != 1 {
		t.Fatalf("want 1 result, got %d", len(results))
	}
	if results[0].Error == nil {
		t.Error("want error for truncated card, got nil")
	}
	if results[0].Card != nil {
		t.Error("want nil card on error")
	}
}

func TestVCard_ParseMalformed_OneBadOneGood(t *testing.T) {
	good := "BEGIN:VCARD\r\nVERSION:4.0\r\nFN:Good\r\nUID:urn:uuid:g\r\nEND:VCARD\r\n"
	// A card whose property line has no value separator is malformed.
	bad := "BEGIN:VCARD\r\nVERSION:4.0\r\nNOSEPARATOR\r\nEND:VCARD\r\n"
	results := contacts.ParseVCards([]byte(good+bad), nil)
	if len(results) != 2 {
		t.Fatalf("want 2 results, got %d", len(results))
	}
	if results[0].Error != nil {
		t.Errorf("good card: unexpected error: %v", results[0].Error)
	}
	// Bad card: either an error or a parsed card — we just require no panic.
}

func TestVCard_ParseEmpty(t *testing.T) {
	if results := contacts.ParseVCards(nil, nil); len(results) != 0 {
		t.Errorf("nil input: want 0 results, got %d", len(results))
	}
	if results := contacts.ParseVCards([]byte{}, nil); len(results) != 0 {
		t.Errorf("empty input: want 0 results, got %d", len(results))
	}
	if results := contacts.ParseVCards([]byte("no cards here"), nil); len(results) != 0 {
		t.Errorf("no-card input: want 0 results, got %d", len(results))
	}
}

func TestVCard_ParseLineFolding(t *testing.T) {
	long := "Very Long Name That Exceeds Seventy Five Octets When Encoded As UTF-8 Indeed"
	// Manually fold at byte 45.
	part1 := long[:45]
	part2 := long[45:]
	vcf := "BEGIN:VCARD\r\nVERSION:4.0\r\nUID:urn:uuid:fold\r\nFN:" +
		part1 + "\r\n " + part2 + "\r\nEND:VCARD\r\n"

	results := contacts.ParseVCards([]byte(vcf), nil)
	if len(results) != 1 || results[0].Error != nil {
		t.Fatalf("unexpected error: %v", func() error {
			if len(results) > 0 {
				return results[0].Error
			}
			return fmt.Errorf("no results")
		}())
	}
	if got := results[0].Card.Name.Full; got != long {
		t.Errorf("Name.Full after fold = %q, want %q", got, long)
	}
}

func TestVCard_ParseEscaping(t *testing.T) {
	vcf := "BEGIN:VCARD\r\nVERSION:4.0\r\nUID:urn:uuid:esc\r\n" +
		`FN:Smith\, John` + "\r\n" +
		`NOTE:Line1\nLine2` + "\r\n" +
		`NOTE:Back\\slash` + "\r\n" +
		"END:VCARD\r\n"

	results := contacts.ParseVCards([]byte(vcf), nil)
	if len(results) != 1 || results[0].Error != nil {
		t.Fatalf("unexpected error: %v", results[0].Error)
	}
	c := results[0].Card
	if c.Name.Full != "Smith, John" {
		t.Errorf("Name.Full = %q, want Smith, John", c.Name.Full)
	}
	assertRawJSONHasNote(t, c, "Line1\nLine2")
	assertRawJSONHasNote(t, c, `Back\slash`)
}

func TestVCard_ParseNonUTF8(t *testing.T) {
	vcf := "BEGIN:VCARD\r\nVERSION:4.0\r\nUID:urn:uuid:enc\r\nFN:Test\xff\xfe\r\nEND:VCARD\r\n"
	results := contacts.ParseVCards([]byte(vcf), nil)
	if len(results) == 0 {
		t.Fatal("want at least 1 result (no panic)")
	}
	// Either a parse error or a card with replacement characters — no panic.
}

