func assertRawJSONHasBirthday(t *testing.T, c *contacts.Card, year, month, day int) {
	t.Helper()
	raw, ok := c.RawJSON["anniversaries"]
	if !ok {
		t.Fatalf("no anniversaries in RawJSON")
	}
	var anns map[string]map[string]interface{}
	if err := json.Unmarshal(raw, &anns); err != nil {
		t.Fatalf("unmarshal anniversaries: %v", err)
	}
	for _, a := range anns {
		if k, _ := a["kind"].(string); k != "birth" {
			continue
		}
		d, _ := a["date"].(map[string]interface{})
		if d == nil {
			continue
		}
		y, _ := d["year"].(float64)
		m, _ := d["month"].(float64)
		dy, _ := d["day"].(float64)
		if int(y) == year && int(m) == month && int(dy) == day {
			return
		}
	}
	t.Errorf("birthday %04d-%02d-%02d not found", year, month, day)
}

func assertRawJSONHasAnniversary(t *testing.T, c *contacts.Card, year, month, day int) {
	t.Helper()
	raw, ok := c.RawJSON["anniversaries"]
	if !ok {
		t.Fatalf("no anniversaries in RawJSON")
	}
	var anns map[string]map[string]interface{}
	if err := json.Unmarshal(raw, &anns); err != nil {
		t.Fatalf("unmarshal anniversaries: %v", err)
	}
	for _, a := range anns {
		if k, _ := a["kind"].(string); k == "birth" {
			continue
		}
		d, _ := a["date"].(map[string]interface{})
		if d == nil {
			continue
		}
		y, _ := d["year"].(float64)
		m, _ := d["month"].(float64)
		dy, _ := d["day"].(float64)
		if (year == 0 || int(y) == year) && int(m) == month && int(dy) == day {
			return
		}
	}
	t.Errorf("anniversary year=%d month=%d day=%d not found", year, month, day)
}

