// ===== set helpers for round-trip comparison =====

func emailAddressSet(c *contacts.Card) map[string]bool {
	m := make(map[string]bool)
	for _, e := range c.Emails {
		m[e.Address] = true
	}
	return m
}

func phoneNumberSet(c *contacts.Card) map[string]bool {
	m := make(map[string]bool)
	for _, p := range c.Phones {
		m[p.Number] = true
	}
	return m
}

func orgNameSet(c *contacts.Card) map[string]bool {
	m := make(map[string]bool)
	for _, o := range c.Organizations {
		m[o.Name] = true
	}
	return m
}

func titleNameSet(c *contacts.Card) map[string]bool {
	m := make(map[string]bool)
	for _, ti := range c.Titles {
		m[ti.Name] = true
	}
	return m
}

func rawJSONNicknameSet(c *contacts.Card) map[string]bool {
	m := make(map[string]bool)
	if c.RawJSON == nil {
		return m
	}
	raw, ok := c.RawJSON["nicknames"]
	if !ok {
		return m
	}
	var nicks map[string]map[string]interface{}
	if err := json.Unmarshal(raw, &nicks); err != nil {
		return m
	}
	for _, n := range nicks {
		if v, _ := n["name"].(string); v != "" {
			m[v] = true
		}
	}
	return m
}

func rawJSONNoteSet(c *contacts.Card) map[string]bool {
	m := make(map[string]bool)
	if c.RawJSON == nil {
		return m
	}
	raw, ok := c.RawJSON["notes"]
	if !ok {
		return m
	}
	var notes map[string]map[string]interface{}
	if err := json.Unmarshal(raw, &notes); err != nil {
		return m
	}
	for _, n := range notes {
		if v, _ := n["note"].(string); v != "" {
			m[v] = true
		}
	}
	return m
}

func rawJSONURLSet(c *contacts.Card) map[string]bool {
	m := make(map[string]bool)
	if c.RawJSON == nil {
		return m
	}
	raw, ok := c.RawJSON["links"]
	if !ok {
		return m
	}
	var links map[string]map[string]interface{}
	if err := json.Unmarshal(raw, &links); err != nil {
		return m
	}
	for _, l := range links {
		if v, _ := l["uri"].(string); v != "" {
			m[v] = true
		}
	}
	return m
}

func rawJSONBirthday(c *contacts.Card) string {
	if c.RawJSON == nil {
		return ""
	}
	raw, ok := c.RawJSON["anniversaries"]
	if !ok {
		return ""
	}
	var anns map[string]map[string]interface{}
	if err := json.Unmarshal(raw, &anns); err != nil {
		return ""
	}
	for _, a := range anns {
		if k, _ := a["kind"].(string); k == "birth" {
			d, _ := a["date"].(map[string]interface{})
			if d == nil {
				continue
			}
			y, _ := d["year"].(float64)
			m, _ := d["month"].(float64)
			dy, _ := d["day"].(float64)
			return fmt.Sprintf("%04d-%02d-%02d", int(y), int(m), int(dy))
		}
	}
	return ""
}

func cardWithNote(note string) *contacts.Card {
	c := &contacts.Card{Version: "1.0", UID: "urn:uuid:note"}
	c.Name = &contacts.Name{Full: "N"}
	c.RawJSON = map[string]json.RawMessage{
		"notes": vcardMustMarshal(map[string]interface{}{
			"n0": map[string]interface{}{"@type": "Note", "note": note},
		}),
	}
	return c
}

func vcardMustMarshal(v interface{}) json.RawMessage {
	b, err := json.Marshal(v)
	if err != nil {
		panic(err)
	}
	return b
}
